local Command = require(script.Parent.Command)
local Connection = require(script.Parent.Parent.Connection)
local WindowManager = require(script.Parent.Parent.WindowManager)

local module = {}
module.__index = module

-- 存储所有ViewModel实例
local _viewmodels = {}

-- 获取指定名称的ViewModel
function module:_getViewModel(name)
    return _viewmodels[name]
end

-- 创建新的ViewModel实例
function module.new(vmScript)
    local self = require(vmScript)
    _viewmodels[vmScript.Name] = self
    
    local mt = {
        _script = vmScript,
        _connectionSymbol = nil,
        _bindingSymbol = nil,
        
        -- 获取模型
        _getModel = function(self, modelName)
            if not self._models[modelName] then
                if vmScript:FindFirstChild("Model") and vmScript.Model:FindFirstChild(modelName) then
                    self._models[modelName] = require(vmScript.Model[modelName])
                else
                    self._models[modelName] = "__null__"
                end
            end
            if self._models[modelName] == "__null__" then
                if not self._globals[modelName] then
                    self._globals[modelName] = require(script.Parent.Model):_getGlobal(modelName) or "__null__"
                end
                if self._globals[modelName] == "__null__" then
                    return nil
                else
                    return self._globals[modelName]
                end
            end
            return self._models[modelName]
        end,
        
        -- 获取视图
        _getView = function(self, viewName)
            if vmScript:FindFirstChild("View") and vmScript.View:FindFirstChild(viewName) then
                return require(vmScript.View[viewName])
            end
        end,
        
        _models = {},
        _globals = {},
        _name = vmScript.Name,
        
        -- 生命周期方法
        Load = function() end,
        Start = function() end
    }

    -- 合并module和self到mt
    for i, v in pairs(module) do
        mt[i] = v
    end
    for i, v in pairs(self) do
        mt[i] = v
        
		-- 处理特殊方法名（OnOpen_, OnClose_, OnShow_, OnHide_）
        if string.find(i, "OnOpen_") == 1 then
            local windowName = string.gsub(i, "OnOpen_", "")
            WindowManager:OnWindowOpened(windowName, function(...)
                v(self, ...)
            end)
        elseif string.find(i, "OnClose_") == 1 then
            local windowName = string.gsub(i, "OnClose_", "")
            WindowManager:OnWindowClosed(windowName, function(...)
                v(self, ...)
            end)
		elseif string.find(i, "OnShow_") == 1 then
            local panelName = string.gsub(i, "OnShow_", "")
            WindowManager:OnPanelShown(panelName, function(...)
                v(self, ...)
            end)
		elseif string.find(i, "OnHide_") == 1 then
            local panelName = string.gsub(i, "OnHide_", "")
            WindowManager:OnPanelHidden(panelName, function(...)
                v(self, ...)
            end)
        end
    end

    -- 设置元表
    setmetatable(self, {
        __index = function(t, k)
            if mt[k] ~= nil then
                return mt[k]
            end
            local value = rawget(t, k)
            if value == nil then
                value = mt:_getModel(k)
            end
            return value
        end,
    })
    
    self:Load()
    return self
end

-- 获取命令
function module:_getCommand(cmd)
    return Command.Get(self, cmd)
end

-- 响应数据变化
function module:Respond(name)
    local names = string.split(name, ".")
    local key = table.remove(names, 1)
    local originValue = self[key]
    while #names > 0 do
        key = table.remove(names, 1)
        if string.find(key, "#") then
            key = string.gsub(key, "#", "")
            key = tonumber(key)
        end
        originValue = originValue[key]
    end
    local event = self:_getModelEvent(name)
    if event then
        event:Fire(originValue)
    end
end

-- 设置可连接属性
function module:_setConnectable(symbol)
    self._connectionSymbol = symbol
end

-- 设置可绑定属性
function module:_setBindable(symbol)
    self._bindingSymbol = symbol
end

-- 检查符号
function module:_checkSymbol(t)
    local symbol = self["_" .. t .. "Symbol"]
    if symbol == nil then
        return true
    end
    if typeof(symbol) == "function" then
        return symbol()
    end
    return symbol
end

-- 连接事件
function module:_connect(...)
    local paras = {...}
    local nameArr = {table.remove(paras, 1)}
    while typeof(paras[1]) == "string" do
        table.insert(nameArr, table.remove(paras, 1))
    end
    
    local originValue = nil
    if #nameArr == 1 then
        local names = string.split(nameArr[1], ".")
        local key = table.remove(names, 1)
        originValue = self[key]
        while #names > 0 do
            key = table.remove(names, 1)
            if string.find(key, "#") then
                key = string.gsub(key, "#", "")
                key = tonumber(key)
            end
            assert(originValue, "[Neza] ".. table.concat(nameArr, ".").. " is nil\n" .. debug.traceback())
            originValue = originValue[key]
        end
    end

    local obj = paras[1]
    local later = paras[#paras]
    if typeof(later) ~= "boolean" then
        later = false
    else
        table.remove(paras, #paras)
    end

    if typeof(obj) == "Instance" then
        -- 处理Instance类型的连接
        local propertyName = paras[2]
        if propertyName and typeof(propertyName) == "string" then
            local callback = paras[3]
            local function update(value, old)
                if obj[propertyName] ~= value then
                    obj[propertyName] = value
                end
            end
            if self:_checkSymbol("connection") then
                if callback then
                    update(callback(originValue))
                else
                    update(originValue)
                end
            end

            local events = {}
            for _, name in ipairs(nameArr) do
                local e = self:_getModelEvent(name).Event
                table.insert(events, e)
            end
            local connection
            if callback then
                connection = Connection.new(events, function(...)
                    if self:_checkSymbol("connection") then
                        update(callback(...))
                    end
                end)
            else
                connection = Connection.new(events, function(...)
                    if self:_checkSymbol("connection") then
                        update(...)
                    end
                end)
            end
            local isdouble = paras[3]
            if isdouble then
                if typeof(isdouble) == "boolean" then
                    obj:GetPropertyChangedSignal(propertyName):Connect(function()
                        if self:_checkSymbol("connection") then
                            -- 双向绑定逻辑
                        end
                    end)
                else
                    obj:GetPropertyChangedSignal(propertyName):Connect(function()
                        if self:_checkSymbol("connection") then
                            -- 双向绑定逻辑
                        end
                    end)
                end
            end
            return connection
        end
    elseif typeof(obj) == "function" then
        -- 处理函数类型的连接
        local callback = paras[1]
        local events = {}
        for _, name in ipairs(nameArr) do
            local e = self:_getModelEvent(name).Event
            table.insert(events, e)
        end
        local connection = Connection.new(events, function(...)
            if self:_checkSymbol("connection") then
                callback(...)
            end
        end, not later, originValue)
        return connection
    else
        warn("[Neza] Connect error: " .. table.concat(nameArr, ".") .. " " .. typeof(obj))
    end
end

-- 获取模型事件
function module:_getModelEvent(name)
    name = string.gsub(name, "#", "")
    local modelName = string.gsub(name, "%..*", "")
    local path = string.sub(name, string.len(modelName) + 2)
    local model = self[modelName]
    if model then
        return model:_getEvent(path)
    end
end

-- 绑定命令
function module:_bind(cmdName, ...)
    local paras = {...}
    local callBack = cmdName
    local this = nil

    if typeof(cmdName) ~= "function" then
        self:_getCommand(cmdName)
        callBack = self[cmdName]
        this = self
    end

    if callBack and typeof(callBack) == "function" then
        local obj = table.remove(paras, 1)
        local signal = nil
        if typeof(obj) == "Instance" then
            signal = obj.MouseButton1Click
        else
            signal = obj
        end
        
        local args = paras
        local connection
        
        connection = Connection.new(signal, function(...)
            local callBackArgs = nil
            if typeof(args[1]) == "function" then
                callBackArgs = table.pack(args[1](connection))
            else
                callBackArgs = args
            end
            if this then
                if self:_checkSymbol("binding") then
                    local command = self:_getCommand(cmdName)
                    local res, err = command:CanExecute(table.unpack(callBackArgs))
                    if res then
                        local execRes = table.pack(command:Execute(table.unpack(callBackArgs)))
                        if connection._then then
                            connection._then(table.unpack(execRes))
                        end
                    elseif connection._catch then
                        connection._catch(err)
                    end
                end
            else
                callBack(table.unpack(callBackArgs))
            end
        end)
        connection.Source = obj
        connection:Named(obj)
        return connection
    else
        warn(cmdName .. " is not a function")
    end
end

-- 解绑命令
function module:_unbind(connectionName)
	return Connection._destroy(connectionName)
end

-- 命令执行后处理
function module:_after(cmdName, ...)
    local paras = {...}
    local this = nil

    if typeof(cmdName) ~= "function" then
        local command = self:_getCommand(cmdName)
        if not command then
            return warn("No " .. cmdName .. " command")
        end
    end
    local callBack = paras[1]
    if typeof(callBack) == "function" then
        local connection
        local command = self:_getCommand(cmdName)
        connection = Connection.new(command._event.Event, function(cmd, ...)
            if cmd ~= "After" then
                return
            end
            callBack(...)
        end)
        return connection
    end
end

-- 绑定方法别名
function module:Bind(...)
    return self:_bind(...)
end

-- 连接方法别名
function module:Connect(...)
    return self:_connect(...)
end

-- 注册窗口、面板或容器
function module:Register(name, _type)
    if _type == "Window" then
        WindowManager:RegisterWindow(self._name, name)
    elseif _type == "Panel" then
        WindowManager:RegisterPanel(self._name, name)
    elseif _type == "Sprite" then
        -- 处理Sprite类型
    elseif _type == "Container" then
        WindowManager:RegisterContainer(self._name, name)
    end
end

-- 添加容器
function module:AddContainer(container, windowName)
    WindowManager:AddContainer(container, windowName)
end

-- 打开窗口
function module:Open(windowName, ...)
    WindowManager:OpenWindow(windowName, ...)
end

-- 关闭窗口
function module:Close(windowName, ...)
    WindowManager:CloseWindow(windowName, ...)
end

-- 返回上一个窗口
function module:Back(windowName, ...)
    WindowManager:BackWindow(windowName, ...)
end

-- 获取容器
function module:GetContainer(container)
    return WindowManager:GetContainer(container)
end

-- 显示面板
function module:ShowPanel(containerName, panelName, ...)
    return WindowManager:ShowPanel(containerName, panelName, ...)
end

-- 隐藏面板
function module:HidePanel(containerName, panelName, ...)
    return WindowManager:HidePanel(containerName, panelName, ...)
end

-- 推入面板
function module:PushPanel(containerName, panelName, ...)
    return WindowManager:PushPanel(containerName, panelName, ...)
end

-- 弹出面板
function module:PopPanel(containerName, panelName, ...)
    return WindowManager:PopPanel(containerName, panelName, ...)
end

-- 清理面板
function module:CleanPanel(containerName, ...)
    return WindowManager:CleanPanel(containerName, ...)
end

return module